/** Conversions between the application models and the "customers" table: what the service takes and returns. */
import type { Address, Customer as CustomerModel, Level, Location } from '../application-models.js'
import type { CustomerCreate, CustomerRead } from '../dtos/customer.js'
import type { Customer } from '../entities/customer.js'

/** A Location as the documents of the customers collection keep it. */
function customerAddressLocationToDocument(value: Location): NonNullable<NonNullable<Customer['address']>['location']> {
  return {
    latitude: value.latitude,
    longitude: value.longitude,
  }
}

/** An Address as the documents of the customers collection keep it. */
function customerAddressToDocument(value: Address): NonNullable<Customer['address']> {
  return {
    street: value.street,
    'zip code': value.zipCode,
    location: value.location == null ? undefined : customerAddressLocationToDocument(value.location),
  }
}

/** A Customer as the customers table takes it. */
export function customerModelToCustomerCreate(model: CustomerModel): CustomerCreate {
  return {
    email: model.email,
    level: model.level == null ? null : String(model.level),
    since: model.since,
    address: customerAddressToDocument(model.address),
    tags: model.tags,
  }
}

/** A document of the customers collection as a Location. */
function customerAddressLocationFromDocument(value: NonNullable<NonNullable<Customer['address']>['location']>): Location {
  return {
    latitude: value.latitude,
    longitude: value.longitude,
  }
}

/** A document of the customers collection as an Address. */
function customerAddressFromDocument(value: NonNullable<Customer['address']>): Address {
  return {
    street: value.street,
    zipCode: value['zip code'],
    location: value.location == null ? undefined : customerAddressLocationFromDocument(value.location),
  }
}

/** A row of the customers table as a Customer. */
export function customerReadToCustomerModel(row: CustomerRead): CustomerModel {
  return {
    id: row.id,
    email: row.email,
    level: row.level == null ? undefined : (row.level as Level),
    since: row.since,
    address: customerAddressFromDocument(row.address),
    tags: row.tags ?? [],
  }
}

