/** The collections of the database, as Mongoose models. They reflect it: Mongoose never creates collections or indexes with them. */
import { Schema, type Connection, type Model } from 'mongoose'

/** A document as the driver gives it, by the stored names of its fields */
export type Stored = Record<string, unknown>

/** The model of every collection */
export interface Models {
  customers: Model<Stored>
  orders: Model<Stored>
  shipments: Model<Stored>
}

/** Defines the model of every collection on `connection`. */
export function defineModels(connection: Connection): Models {
  /** The 'customers' collection. */
  const customers = new Schema(
    {
      email: { type: String, required: true },
      level: { type: String, enum: ['basic', 'gold'] },
      since: { type: Date, required: true },
      address: { type: new Schema({ street: { type: String, required: true }, 'zip code': { type: String, required: true }, location: new Schema({ latitude: { type: Schema.Types.Double, required: true }, longitude: { type: Schema.Types.Double, required: true } }, { _id: false, strict: false, minimize: false }) }, { _id: false, strict: false, minimize: false }), required: true },
      tags: { type: [String], default: undefined },
    },
    { collection: 'customers', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )
  customers.index({ email: 1 }, { unique: true })

  /** The 'orders' collection. */
  const orders = new Schema(
    {
      code: { type: String, required: true },
      lines: { type: [new Schema({ sku: { type: String, required: true }, quantity: { type: Number, required: true }, price: { type: Schema.Types.Decimal128, required: true }, status: { type: String, enum: ['pending', 'sent'] }, discounts: { type: [new Schema({ reason: { type: String, required: true }, percent: { type: Schema.Types.Double, required: true } }, { _id: false, strict: false, minimize: false })], default: undefined } }, { strict: false, minimize: false })], default: undefined, required: true },
      shipping: new Schema({ carrier: { type: String, required: true }, sentOn: { type: Date, required: true } }, { _id: false, strict: false, minimize: false }),
    },
    { collection: 'orders', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )
  orders.index({ code: 1 }, { unique: true })

  /** The 'shipments' collection. */
  const shipments = new Schema(
    {
      parcel: { type: new Schema({ weight: { type: Schema.Types.Double, required: true }, contents: { type: String, required: true }, size: new Schema({ height: { type: Schema.Types.Double, required: true } }, { _id: false, strict: false, minimize: false }) }, { _id: false, strict: false, minimize: false }), required: true },
      stops: { type: [new Schema({ city: String }, { _id: false, strict: false, minimize: false })], default: undefined },
    },
    { collection: 'shipments', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )

  return {
    customers: connection.model<Stored>('Customer', customers as unknown as Schema<Stored>),
    orders: connection.model<Stored>('Order', orders as unknown as Schema<Stored>),
    shipments: connection.model<Stored>('Shipment', shipments as unknown as Schema<Stored>),
  }
}

