    row.stops = [...(row.stops ?? []), stop]
    return row
  }

  /** Removes an item from stops that has this size, and returns the row as it is then, or null when there is none. */
  async removeStop(id: string, position: number, size: number): Promise<Shipment | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    if ((row.stops ?? []).length !== size) return null
    row.stops = (row.stops ?? []).filter((_, index) => index !== position)
    return row
  }
}

