import { problems, type Rule } from '../documents.js'
import type { CustomerCreate, CustomerRead, CustomerUpdate } from '../dtos/customer.js'
import { Customer } from '../entities/customer.js'
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { Page } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['email', 'level', 'since', 'address', 'tags'])

/** The rules of the documents and lists inside each one */
const DOCUMENTS = {
  address: { fields: { street: { required: true }, 'zip code': { required: true }, location: { fields: { latitude: { required: true }, longitude: { required: true } } } } },
} satisfies Record<string, Rule>

/** Operations on customers. Repositories commit every write. */
export class CustomerService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "customers" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Customer | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Customer' })
    if (!creating) for (const name of Object.keys(values)) if (['id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.email
      if (value == null) {
        if (creating || 'email' in values) errors.push({ field: 'email', message: 'is required' })
      }
    }
    {
      const value = values.level
      if (value != null) {
        if (!['basic', 'gold'].includes(value as never)) errors.push({ field: 'level', message: 'must be one of: basic, gold' })
      }
    }
    {
      const value = values.since
      if (value == null) {
        if (creating || 'since' in values) errors.push({ field: 'since', message: 'is required' })
      }
    }
    {
      const value = values.address
      if (value == null) {
        if (creating || 'address' in values) errors.push({ field: 'address', message: 'is required' })
      } else {
        errors.push(...problems(value, DOCUMENTS.address, 'address'))
      }
    }
    if (errors.length > 0) throw new ValidationFailedError('Customer', errors)
  }

  /** Values that must be unique are not taken by another row. */
  private async checkUnique(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Customer | null): Promise<void> {
    {
      const email = ('email' in values ? values.email : current?.email) as string | null | undefined
      if (email != null) {
        const other = await uow.customers.findByEmail(email)
        if (other !== null && (current === null || other.id !== current.id))
          throw new ConflictError('Customer', 'email is already taken', ['email'])
      }
    }
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Customer | null): Promise<void> {
    await this.validate(uow, values, current)
    await this.checkUnique(uow, values, current)
  }

  /** The Customer with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: string): Promise<Customer> {
    const entity = await uow.customers.findById(id)
    if (entity === null) throw new NotFoundError('Customer', id)
    return entity
  }

  /** The Customer as services return it. */
  private static read(entity: Customer): CustomerRead {
    return { id: entity.id, email: entity.email, level: entity.level, since: entity.since, address: entity.address, tags: entity.tags }
  }

  /** Stores a new Customer after checking it. */
  async createCustomer(data: CustomerCreate): Promise<CustomerRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.customers.insert(Object.assign(new Customer(), values))
      return CustomerService.read(created)
    })
  }

  /** The Customer with this key; NotFoundError when there is none. */
  async getCustomer(id: string): Promise<CustomerRead> {
    return CustomerService.read(await this.find(this.uow, id))
  }

  /** A page of customers, by primary key. */
  async listCustomers(offset = 0, limit = 50): Promise<Page<CustomerRead>> {
    const page = await this.uow.customers.list(offset, limit)
    return { ...page, items: page.items.map((entity) => CustomerService.read(entity)) }
  }

  /** Changes the given values of a Customer. */
  async updateCustomer(id: string, data: CustomerUpdate): Promise<CustomerRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.customers.update(current)
      return CustomerService.read(updated)
    })
  }

  /** Deletes a Customer. */
  async deleteCustomer(id: string): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await uow.customers.delete(current)
    })
  }

  /** The Customer with this email, or null. */
  async findCustomerByEmail(email: string): Promise<CustomerRead | null> {
    const entity = await this.uow.customers.findByEmail(email)
    return entity === null ? null : CustomerService.read(entity)
  }

  /** Adds an item to tags. */
  async addTag(id: string, tag: string): Promise<CustomerRead> {
    return this.uow.transaction(async (uow) => {
      await this.find(uow, id)
      const updated = await uow.customers.addTag(id, tag)
      if (updated === null) throw new NotFoundError('Customer', id)
      return CustomerService.read(updated)
    })
  }

  /** Removes an item from tags, by its value. */
  async removeTag(id: string, tag: string): Promise<CustomerRead> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (!(current.tags ?? []).includes(tag)) throw new NotFoundError('Tag', tag)
      const updated = await uow.customers.removeTag(id, tag)
      if (updated === null) throw new NotFoundError('Customer', id)
      return CustomerService.read(updated)
    })
  }
}

