/** Rows for the tests: valid values for every column, and the rows they point to. */
import { Customer } from '../src/entities/customer.js'
import { Order } from '../src/entities/order.js'
import { Shipment } from '../src/entities/shipment.js'
import type { UnitOfWork } from '../src/unit-of-work.js'

/** A valid Customer that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newCustomer(n = 1, values: Partial<Customer> = {}): Customer {
  return Object.assign(new Customer(), { email: `email-${n}`, level: 'basic', since: new Date(Date.UTC(2026, 0, (n % 28) + 1, 12, 0, 0)), address: { street: `street-${n}`, 'zip code': `zipcode-${n}`, location: { latitude: n + 0.5, longitude: n + 0.5 } }, tags: [] }, values)
}

/** A stored Customer. */
export async function addCustomer(uow: UnitOfWork, n = 1): Promise<Customer> {
  return uow.customers.insert(newCustomer(n))
}

/** A valid Order that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newOrder(n = 1, values: Partial<Order> = {}): Order {
  return Object.assign(new Order(), { code: `code-${n}`, lines: [{ sku: `sku-${n}`, quantity: n, price: `${n % 10000}.50`, status: 'pending', discounts: [{ reason: `reason-${n}`, percent: n + 0.5 }] }], shipping: { carrier: `carrier-${n}`, sentOn: new Date(Date.UTC(2026, 0, (n % 28) + 1, 12, 0, 0)) } }, values)
}

/** A stored Order. */
export async function addOrder(uow: UnitOfWork, n = 1): Promise<Order> {
  return uow.orders.insert(newOrder(n))
}

/** A valid Shipment that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newShipment(n = 1, values: Partial<Shipment> = {}): Shipment {
  return Object.assign(new Shipment(), { parcel: { weight: n + 0.5, contents: `contents-${n}`, size: { height: n + 0.5 } }, stops: [{ city: `city-${n}` }] }, values)
}

/** A stored Shipment. */
export async function addShipment(uow: UnitOfWork, n = 1): Promise<Shipment> {
  return uow.shipments.insert(newShipment(n))
}

